def skjkasdkd(lst):
    """You are given a list of integers.
    You need to find the largest prime value and return the sum of its digits.

    Examples:
    For lst = [0,3,2,1,3,5,7,4,5,5,5,2,181,32,4,32,3,2,32,324,4,3] the output should be 10
    For lst = [1,0,1,8,2,4597,2,1,3,40,1,2,1,2,4,2,5,1] the output should be 25
    For lst = [1,3,1,32,5107,34,83278,109,163,23,2323,32,30,1,9,3] the output should be 13
    For lst = [0,724,32,71,99,32,6,0,5,91,83,0,5,6] the output should be 11
    For lst = [0,81,12,3,1,21] the output should be 3
    For lst = [0,8,1,2,1,7] the output should be 7
    """
    def is_prime(n):
        """Return True if n is a prime number, else False."""
        if n < 2:
            return False
        if n in (2, 3):
            return True
        if n % 2 == 0 or n % 3 == 0:
            return False
        # check divisors of the form 6k ± 1 up to sqrt(n)
        i = 5
        while i * i <= n:
            if n % i == 0 or n % (i + 2) == 0:
                return False
            i += 6
        return True

    max_prime = None
    for num in lst:
        if is_prime(num):
            if max_prime is None or num > max_prime:
                max_prime = num

    if max_prime is None:
        return 0

    # sum of digits of the largest prime
    return sum(int(digit) for digit in str(max_prime))

from collections import Counter
def histogram(test):
    """Given a string representing a space separated lowercase letters, return a dictionary
    of the letter with the most repetition and containing the corresponding count.
    If several letters have the same occurrence, return all of them.

    Example:
    histogram('a b c') == {'a': 1, 'b': 1, 'c': 1}
    histogram('a b b a') == {'a': 2, 'b': 2}
    histogram('a b c a b') == {'a': 2, 'b': 2}
    histogram('b b b b a') == {'b': 4}
    histogram('') == {}

    """
    # Handle empty or whitespace‑only input
    if not test or test.strip() == '':
        return {}

    # Split on any whitespace to obtain the individual letters
    letters = test.split()

    # Count occurrences of each letter
    freq = Counter(letters)

    # Determine the highest frequency
    max_count = max(freq.values())

    # Build the result containing all letters that have the max frequency
    result = {letter: max_count for letter, count in freq.items() if count == max_count}

    return result

def encode(message):
    """
    Write a function that takes a message, and encodes in such a 
    way that it swaps case of all letters, replaces all vowels in 
    the message with the letter that appears 2 places ahead of that 
    vowel in the english alphabet. 
    Assume only letters. 

    Examples:
    >>> encode('test')
    'TGST'
    >>> encode('This is a message')
    'tHKS KS C MGSSCGG'
    """
    # Helper: swap case of a single character
    def swap_case(ch):
        return ch.lower() if ch.isupper() else ch.upper() if ch.islower() else ch

    # Helper: check if a character is a vowel (after case swap)
    def is_vowel(ch):
        return ch.lower() in {'a', 'e', 'i', 'o', 'u'}

    # Helper: two‑place‑ahead of a vowel, preserving case
    def two_ahead(ch):
        # Determine the base alphabet (a‑z) and the offset
        if ch.islower():
            base = ord('a')
        else:
            base = ord('A')
        # Position of the vowel in the alphabet (0‑based)
        pos = (ord(ch) - base)
        # Two positions ahead, wrap only if we go beyond 'z' (not required by spec)
        new_pos = (pos + 2) % 26
        return chr(base + new_pos)

    encoded_chars = []
    for ch in message:
        if ch.isalpha():
            swapped = swap_case(ch)
            if is_vowel(swapped):
                encoded_chars.append(two_ahead(swapped))
            else:
                encoded_chars.append(swapped)
        else:
            # Non‑alphabetic characters (e.g., spaces) stay unchanged
            encoded_chars.append(ch)

    return ''.join(encoded_chars)
